  /* --- the mask reveals ----------------------------------------------------
     A frame opens as it enters. IntersectionObserver, not ScrollTrigger: a
     class toggle is all it needs and it has to work without GSAP. */
  function masks() {
    var items = $$('[data-j="mask"]');
