  /* --- the ghost words -----------------------------------------------------
     Drift sideways with the scroll. Decoration; aria-hidden in the markup. */
  function ghosts() {
    if (!useGsap) return;
    $$(".ghost_word").forEach(function (el) {
      var dir = el.classList.contains("is-right") ? 1 : -1;
      gsap.fromTo(
        el,
        { xPercent: dir * 6 },
        {
          xPercent: dir * -6,
          ease: "none",
