     lag, and swaps its photograph to the row under the pointer. */
  function concerns() {
    var root = $(".concern_component");
    if (!root) return;
    var frame = $(".concern_float", root);
    var rows = $$(".concern_row", root);
    if (!frame || !rows.length || !finePointer || reduce) return;
    var imgs = $$("img", frame);
    var tx = 0,
      ty = 0,
      cx = 0,
      cy = 0,
      raf = null,
      on = false;
    var tick = function () {
      cx += (tx - cx) * 0.14;
      cy += (ty - cy) * 0.14;
