      if (reduce || paused) return;
      if (bar) bar.classList.add("is-running");
      timer = setTimeout(function () {
        go(i + 1);
      }, 7000);
    };
    if (prev)
      prev.addEventListener("click", function () {
        go(i - 1);
      });
    if (next)
      next.addEventListener("click", function () {
        go(i + 1);
      });
